// The command line in Homebrew and Scoop (#1430): write the Homebrew formula
// and the Scoop manifest of a release from its SHA256SUMS. Both point at the
// executables of the GitHub Release, so nothing is built twice.
//
//   node .github/scripts/package-managers.mjs <version> <SHA256SUMS> <tap-dir> <bucket-dir>
//
// writes <tap-dir>/Formula/postext.rb and <bucket-dir>/bucket/postext.json.
// The release workflow runs it on checkouts of drnachio/homebrew-postext and
// drnachio/scoop-postext and pushes what changed; the files there are
// generated, so edit them here. Plain Node, no dependencies.

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const [version, sumsPath, tapDir, bucketDir] = process.argv.slice(2);
if (!version || !sumsPath || !tapDir || !bucketDir || !/^\d+\.\d+\.\d+$/.test(version)) {
  console.error('usage: package-managers.mjs <version> <SHA256SUMS> <tap-dir> <bucket-dir>');
  process.exit(2);
}

// "<sha256>  <file>" per line → file → sha256
const sums = new Map();
for (const line of readFileSync(sumsPath, 'utf8').split('\n')) {
  const m = /^([0-9a-f]{64})\s+\*?(\S+)\s*$/.exec(line.trim());
  if (m) sums.set(m[2], m[1]);
}

function sha(file) {
  const hash = sums.get(file);
  if (!hash) throw new Error(`${file} is not in ${sumsPath}`);
  return hash;
}

const BASE = `https://github.com/drnachio/postext/releases/download/v${version}`;
const DESC = 'Typeset books from Markdown: PDF, HTML, EPUB, page images and Word';

const asset = (file) => `      url "${BASE}/${file}"\n      sha256 "${sha(file)}"`;

const formula = `# Generated by the release workflow of drnachio/postext
# (.github/scripts/package-managers.mjs): edit it there, not here.
class Postext < Formula
  desc "${DESC}"
  homepage "https://postext.dev/"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
${asset('postext-macos-arm64')}
    end
    on_intel do
${asset('postext-macos-x64')}
    end
  end

  on_linux do
    on_arm do
${asset('postext-linux-arm64')}
    end
    on_intel do
${asset('postext-linux-x64')}
    end
  end

  def install
    bin.install Dir["postext-*"].first => "postext"
  end

  test do
    assert_match "postext #{version}", shell_output("#{bin}/postext --version")
  end
end
`;

const windows = 'postext-windows-x64.exe';
const manifest = {
  version,
  description: `${DESC}. One self-contained executable: the postext engine, its PDF, EPUB, HTML and Word writers, fonts and print profiles.`,
  homepage: 'https://postext.dev/',
  license: 'MIT',
  architecture: {
    '64bit': {
      url: `${BASE}/${windows}#/postext.exe`,
      hash: sha(windows),
    },
  },
  bin: 'postext.exe',
  checkver: { github: 'https://github.com/drnachio/postext' },
  autoupdate: {
    architecture: {
      '64bit': {
        url: `https://github.com/drnachio/postext/releases/download/v$version/${windows}#/postext.exe`,
        hash: {
          url: 'https://github.com/drnachio/postext/releases/download/v$version/SHA256SUMS',
          regex: `([a-fA-F0-9]{64})\\s+\\*?${windows.replace(/\./g, '\\.')}`,
        },
      },
    },
  },
};

mkdirSync(join(tapDir, 'Formula'), { recursive: true });
writeFileSync(join(tapDir, 'Formula', 'postext.rb'), formula);
mkdirSync(join(bucketDir, 'bucket'), { recursive: true });
writeFileSync(join(bucketDir, 'bucket', 'postext.json'), JSON.stringify(manifest, null, 4) + '\n');
console.log(`postext ${version}: Formula/postext.rb and bucket/postext.json written`);
